public ServiceResult topUpWallet(String raceId, TopUpWalletRequest request) {
    return withIdempotency(request.requestId(), "TOP_UP_WALLET",
            orderedParams(
                    "raceId", raceId,
                    "bib", request.bib(),
                    "transactionId", request.transactionId(),
                    "amount", request.amount(),
                    "expectedVersion", request.expectedVersion()),
            () -> {
                // transactionId 为第二层全局幂等键：同参重放首次入账结果，异参409。
                WalletTransactionRow existing =
                        repository.findWalletTransaction(request.transactionId()).orElse(null);
                if (existing != null) {
                    return replayTopUpOrConflict(raceId, request, existing);
                }
                RaceRow race = requireOpenRace(raceId, request.expectedVersion());
                RunnerRow runner = requireRunner(raceId, request.bib());
                int amount = request.amount();
                bumpVersion(race, request.expectedVersion());
                long now = clock.millis();
                int balanceAfter = runner.balance() + amount;
                repository.increaseBalance(raceId, request.bib(), amount);
                repository.insertWalletTransaction(new WalletTransactionRow(
                        request.transactionId(), raceId, request.bib(), null,
                        WalletTransactionType.TOPUP, amount, balanceAfter, now));
                return ServiceResult.created(new WalletResponse(raceId, request.bib(), balanceAfter));
            });
}

