                    throw new NotFoundException("申诉不属于该赛事: " + protestId);
                }
                if (protest.status() != ProtestStatus.PENDING) {
                    // 重复裁决或终态改判：直接409，且下面的条件 UPDATE 保证不会再次退款/没收。
                    throw new ConflictException(
                            "申诉已裁决，裁决为终态不可更改: " + protestId);
